-- Hand-written steps (DB-04): only what the ORM cannot express, each with a comment saying why.

-- AUD-05: the database itself rejects changes to stored audit events; the ORM cannot declare
-- triggers. The trigger is per statement, so it also rejects an UPDATE that matches no rows and
-- INSERT ... ON CONFLICT DO UPDATE. DELETE stays possible for the retention job, the only code
-- that removes events (AUD-04, RET-02).
CREATE FUNCTION audit_event_reject_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit events are append-only (AUD-05)' USING ERRCODE = 'restrict_violation';
END
$$;
CREATE TRIGGER audit_event_append_only BEFORE UPDATE OR TRUNCATE ON audit_event
    FOR EACH STATEMENT EXECUTE FUNCTION audit_event_reject_change();
